"""Write the colour maps of the Rust frontends (256 entries each, sampled from matplotlib).

Usage: uv run export_colormaps.py > ../crates/transverse-lines/src/render/colormap_data.rs
"""

import sys

from matplotlib import colormaps


def table(name: str) -> str:
    cmap = colormaps[name]
    rows = []
    for i in range(256):
        r, g, b, _ = cmap(i / 255)
        rows.append(f"[{round(r * 255)}, {round(g * 255)}, {round(b * 255)}]")
    return ",\n    ".join(rows)


def main() -> None:
    out = [
        "// Generated by python/export_colormaps.py from matplotlib. Do not edit.",
        "",
    ]
    for name in ("inferno", "viridis"):
        out += [f"pub const {name.upper()}: [[u8; 3]; 256] = [", f"    {table(name)},", "];", ""]
    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
